  const lang = getLang(), tx = tr(lang), q = String(searchParams.q || '').slice(0, 80), user = await getUser(), like = `%${q}%`;
  const [pr, ls, sv] = await Promise.all([
    pool.query('SELECT id,title FROM projects WHERE title ILIKE $1 OR description ILIKE $1 OR language ILIKE $1 LIMIT 20', [like]),
    pool.query('SELECT id,title FROM lessons WHERE title ILIKE $1 OR language ILIKE $1 LIMIT 20', [like]),
    user ? pool.query('SELECT id,name AS title FROM servers WHERE user_id=$1 AND name ILIKE $2 LIMIT 20', [user.id, like]) : { rows: [] },
  ]);
  const langs = LANGS.filter((l) => l.toLowerCase().includes(q.toLowerCase()));
