import Link from 'next/link';
import { pool } from '@/lib/db';
import { getUser } from '@/lib/auth';
import { getLang, tr } from '@/lib/i18n';
import { LANGS, LEVELS } from '@/lib/consts';
export const dynamic = 'force-dynamic';
export default async function Learn({ searchParams }) {
  const lang = getLang(), tx = tr(lang), user = await getUser();
  const { q = '', language = '', level = '' } = searchParams;
  const w = [], p = [];
  if (q) { p.push(`%${q}%`); w.push(`title ILIKE $${p.length}`); }
  if (LANGS.includes(language)) { p.push(language); w.push(`language=$${p.length}`); }
  if (LEVELS[level]) { p.push(level); w.push(`level=$${p.length}`); }
  const { rows } = await pool.query(`SELECT id,title,language,level FROM lessons ${w.length ? 'WHERE ' + w.join(' AND ') : ''}
    ORDER BY language, CASE level WHEN 'beginner' THEN 1 WHEN 'intermediate' THEN 2 ELSE 3 END, position, id`, p);
  const done = user ? new Set((await pool.query('SELECT lesson_id FROM lesson_progress WHERE user_id=$1', [user.id])).rows.map((r) => r.lesson_id)) : new Set();
  const completed = rows.filter((r) => done.has(r.id)).length, pct = rows.length ? Math.round(completed / rows.length * 100) : 0;
  const groups = {}; rows.forEach((r) => { (groups[r.language || '—'] ||= []).push(r); });
  return (<>
    <h2>{tx('تعليم البرمجة', 'Learn programming')}</h2>
    <form className="filters"><input name="q" defaultValue={q} placeholder={tx('ابحث في الدروس', 'Search lessons')} />
      <select name="language" defaultValue={language}><option value="">{tx('كل اللغات', 'All languages')}</option>{LANGS.map((l) => <option key={l}>{l}</option>)}</select>
      <select name="level" defaultValue={level}><option value="">{tx('كل المستويات', 'All levels')}</option>{Object.entries(LEVELS).map(([k, v]) => <option key={k} value={k}>{tx(...v)}</option>)}</select>
      <button className="btn primary">{tx('تصفية', 'Filter')}</button></form>
    {user && rows.length > 0 && <div className="card"><div className="row" style={{ justifyContent: 'space-between' }}><span>{tx('تقدمك', 'Your progress')}</span><b>{completed}/{rows.length}</b></div><div className="bar"><i style={{ width: pct + '%' }} /></div></div>}
    {rows.length === 0 && <p className="muted">{tx('لا توجد دروس بعد.', 'No lessons yet.')}</p>}
    {Object.entries(groups).map(([g, ls]) => (<section key={g}><h2>{g}</h2><div className="grid">
      {ls.map((l) => <Link key={l.id} href={`/learn/${l.id}`} className="card"><b>{done.has(l.id) && <span className="ok">✓ </span>}{l.title}</b>
        <div><span className="badge">{LEVELS[l.level] ? tx(...LEVELS[l.level]) : l.level}</span></div></Link>)}
    </div></section>))}
  </>);
}

app/learn/[id]/page.js:
import Link from 'next/link';
import { notFound } from 'next/navigation';
import { pool } from '@/lib/db';
import { getUser } from '@/lib/auth';
import { getLang, tr } from '@/lib/i18n';
import { LEVELS } from '@/lib/consts';
import CodeBlock from '@/components/CodeBlock';
import LessonClient from '@/components/LessonClient';
export const dynamic = 'force-dynamic';
export default async function Lesson({ params }) {
  if (!/^\d{1,9}$/.test(params.id)) notFound();
  const lang = getLang(), tx = tr(lang), user = await getUser();
  const { rows: [l] } = await pool.query('SELECT * FROM lessons WHERE id=$1', [params.id]);
  if (!l) notFound();
  const { rows: [nx] } = await pool.query('SELECT id,title FROM lessons WHERE language IS NOT DISTINCT FROM $1 AND (position,id) > ($2,$3) ORDER BY position,id LIMIT 1', [l.language, l.position, l.id]);
  const done = user ? (await pool.query('SELECT 1 FROM lesson_progress WHERE user_id=$1 AND lesson_id=$2', [user.id, l.id])).rowCount > 0 : false;
  const paras = (s) => s.split(/\n{2,}/).filter(Boolean).map((x, i) => <p key={i} style={{ whiteSpace: 'pre-wrap', lineHeight: 1.8 }}>{x}</p>);
  return (<>
    <p className="muted"><Link href={`/learn?language=${encodeURIComponent(l.language || '')}`}>{l.language}</Link> · {LEVELS[l.level] ? tx(...LEVELS[l.level]) : l.level}</p>
    <h1>{l.title}</h1>{paras(l.content)}
    {l.code && (<><h2>{tx('مثال', 'Example')}</h2><CodeBlock code={l.code} lang={lang} />{l.code_explain && <div className="card">{paras(l.code_explain)}</div>}</>)}
    <LessonClient id={l.id} done={done} loggedIn={!!user} playground={l.playground} quiz={l.quiz} lang={lang} nextId={nx?.id || null} />
  </>);
}
